#!/usr/bin/env python3
# =====================================================================
#  apply_tg_sender_vet.py  —  fence TG_SENDER_VET_20261111
#  REQUIRES apply_wing_fast_fill.py (and the three before it).
#
#  Two Telegram findings from the "Market Makers" channel, 11 Nov 2026:
#
#   1. Posts in a Telegram CHANNEL always show the channel's name, never
#      the bot's, so two installs posting there looked identical.
#      → telegram_api.py / telegram_summary_send.py: in channels and
#        groups (negative chat ids) every message and every card caption
#        (daily summary, expiry card, parity card) opens with
#        "🤖 <bot's own name>", read once from Telegram (getMe) and cached.
#        Private chats unchanged. No setting needed: each install's bot
#        already has its own name. Fail-open — no name, no prefix.
#
#   2. Velvet never sent Trade Activity (entries / exits) to Telegram —
#      every other fleet strategy does. The friend's live Icarus entry
#      arrived; his live Velvet entry could not.
#      → vet_manager.py: the same BASKET ENTRY / BASKET EXIT messages
#        Tigris and Icarus send (paper and live, both close paths), routed
#        by each channel's existing Trade Activity / mode / strategy
#        filters. Best-effort: a Telegram failure never blocks a trade.
#        Off inside test processes (no junk cards or in-app events).
#
#   tests  app/api/test_tg_sender_vet.py (15 checks) + the Velvet suites
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_tg_sender_vet.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "TG_SENDER_VET_20261111"
ITEMS = json.loads(r'''[{"path": "backend/app/api/telegram_api.py", "orig": "c1f967cd5cfae7ab96d4036daa29d6c0480c0562f979caf4ffa3f5eecc23fa3c", "new": "be978e9263e0398229c8f7ca383aa5c33a20185d10c6fab3b28ce1407354ee63", "blob": ""}, {"path": "backend/app/api/telegram_summary_send.py", "orig": "40c59e819160576d501f9cd8fc784617218b6c608956cbd5bd10a4e54bf6f898", "new": "c166452361dca9756c4c9301c89ecfa0fd99d08357945a0635db2e00224a71f0", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "b8041215aeb158427ca5db12115b54c21cf6611910f18523555fb1e46fc12137", "new": "bd5d34d244a2a34ce8c02366514527fb947785debfb685191d451148da33d3fa", "blob": ""}, {"path": "backend/app/api/test_tg_sender_vet.py", "orig": null, "new": "0a56f295fe85103ed71c5a01348f7f7026c409431b0d4e53dd9e87a865e6066f", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/api/test_tg_sender_vet.py",
         "app/engine/vet/test_vet_e2e.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_wing_far.py", "app/engine/vet/test_vet_live_confirm.py",
         "app/engine/vet/test_vet_near_obs.py", "app/engine/vet/test_vet_gap_close.py",
         "app/engine/vet/test_vet_live_dte_lots.py", "app/engine/vet/test_vet_sltp_live.py",
         "app/execution/test_wing_fast_fill.py", "app/slippage/test_slip.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_wing_fast_fill.py (Velvet's manager builds on it)
if "--rollback" not in args:
    try:
        _ok = "WING_FAST_FILL_20261111" in open(os.path.join(
            repo, "backend/app/engine/vet/vet_manager.py"), encoding="utf-8").read()
    except OSError:
        _ok = False
    if not _ok:
        die("run apply_wing_fast_fill.py first (and the three before it)")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="tg_sender_vet_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_tg_sender_vet.py --rollback")
